using SoulsFormats;using System.Text.Json;using System.Security.Cryptography;using System.Numerics;
static class MapParishBellAudit {
static string Leaf(string p)=>Path.GetFileName(p.Replace('\\','/'));
static void Main(string[] args){string source=args[0],native=args[1],defs=args[2],output=args[3];Directory.CreateDirectory(output);var hashes=new Dictionary<string,string>();byte[] Read(string root,string p){var path=Path.Combine(root,p);var b=File.ReadAllBytes(path);hashes[path]=Convert.ToHexStringLower(SHA256.HashData(b));return b;}
var game=BND3.Read(Read(source,"param/GameParam/GameParam.parambnd.dcx"));var actions=PARAM.Read(game.Files.Single(f=>Leaf(f.Name)=="ObjActParam.param").Bytes);actions.ApplyParamdef(PARAMDEF.XmlDeserialize(Path.Combine(defs,"ObjActParam.xml")));
File.WriteAllText(Path.Combine(output,"source-objact.json"),JsonSerializer.Serialize(actions.Rows.Where(r=>r.ID==1202).Select(r=>new{r.ID,r.Name,Cells=r.Cells.ToDictionary(c=>c.Def.InternalName,c=>Convert.ToString(c.Value,System.Globalization.CultureInfo.InvariantCulture))}),new JsonSerializerOptions{WriteIndented=true}));
var sourceBytes=Read(source,"obj/o1202.objbnd.dcx");var bank=BND3.Read(sourceBytes);var visual=FLVER2.Read(bank.Files.Single(f=>f.ID==200).Bytes);var animations=BND3.Read(bank.Files.Single(f=>f.ID==400).Bytes);var clips=animations.Files.Where(f=>f.ID<10000).Select(f=>{var a=SourceAnimation.Decode(animations.Files.Single(f=>f.ID==1000000).Bytes.ToArray(),f.Bytes.ToArray());return new{f.ID,f.Name,a.Duration,a.FrameCount,a.FrameDuration,Bones=a.Bones.Select((b,i)=>new{Index=i,b.Name,b.Parent,b.Translation,b.Rotation,b.Scale}),Start=a.Sample(0),Middle=a.Sample(a.Duration*.5f),End=a.Sample(a.Duration)};}).ToArray();
var physics=bank.Files.SingleOrDefault(f=>f.ID==300)?.Bytes.ToArray();var bodyReports=new List<object>();if(physics!=null){var tag=new SourceCollision.Tag(physics);foreach(var b in tag.Items.Where(i=>i.Count==1&&tag.Name(i.Type)=="hkpRigidBody")){var text=tag.Reference(tag.Nested(b.Type,b.At,"name").At);var shape=tag.Reference(tag.Nested(b.Type,b.At,"collidable","shape").At);string type=tag.Name(shape.Type);var child=type=="hkpConvexTranslateShape"?tag.Reference(tag.Nested(shape.Type,shape.At,"childShape","childShape").At):shape;bodyReports.Add(new{Name=SourceAnimation.DecodeBoneName(physics.AsSpan(text.At,text.Count-1).ToArray()),Type=type,Child=tag.Name(child.Type),Translation=type=="hkpConvexTranslateShape"?tag.Vector(tag.Nested(shape.Type,shape.At,"translation").At):Vector3.Zero,Half=tag.Name(child.Type)=="hkpBoxShape"?tag.Vector(tag.Nested(child.Type,child.At,"halfExtents").At):Vector3.Zero,Rest=tag.Transform(tag.Nested(b.Type,b.At,"motion","motionState","transform").At)});}}
File.WriteAllText(Path.Combine(output,"source-assets.json"),JsonSerializer.Serialize(new{Hash=Convert.ToHexStringLower(SHA256.HashData(sourceBytes)),Files=bank.Files.Select(f=>new{f.ID,f.Name,Length=f.Bytes.Length}),Nodes=visual.Nodes.Select((n,i)=>new{Index=i,n.Name,n.ParentIndex,n.Translation,n.Rotation,n.Scale}),Dummies=visual.Dummies.Select(d=>new{d.ReferenceID,d.ParentBoneIndex,d.AttachBoneIndex,d.Position,d.Forward,d.Upward}),Meshes=visual.Meshes.Select(m=>new{m.MaterialIndex,m.Dynamic,Vertices=m.Vertices.Count,Nodes=m.Vertices.Select(v=>v.BoneIndices[0]).Distinct().ToArray(),m.BoneIndices}),Bodies=bodyReports,Clips=clips},new JsonSerializerOptions{WriteIndented=true,IncludeFields=true}));
var nativeMap=MSBB.Read(Read(native,"map/MapStudio/m24_02_00_00.msb.dcx"));var nativeGame=BND4.Read(Read(native,"param/gameparam/gameparam.parambnd.dcx"));var pa=PARAM.Read(nativeGame.Files.Single(f=>Leaf(f.Name)=="ObjActParam.param").Bytes);pa.ApplyParamdef(PARAMDEF.XmlDeserialize(Path.GetFullPath(Path.Combine(defs,"../../BB/Defs/ObjActParam.xml"))));
File.WriteAllText(Path.Combine(output,"native-levers.json"),JsonSerializer.Serialize(new{Actions=nativeMap.Events.ObjActs.Where(a=>a.ObjActParamID==2420000).Select(a=>new{a.ObjActPartName,a.ObjActEntityID,a.ObjActParamID,a.ObjActState,a.EventFlagID,Part=nativeMap.Parts.Objects.Where(p=>p.Name==a.ObjActPartName).Select(p=>new{p.Name,p.ModelName,p.EntityID,p.Position,p.Rotation,p.Scale})}),Params=pa.Rows.Where(r=>r.ID==2420000).Select(r=>new{r.ID,r.Name,Cells=r.Cells.ToDictionary(c=>c.Def.InternalName,c=>Convert.ToString(c.Value,System.Globalization.CultureInfo.InvariantCulture))})},new JsonSerializerOptions{WriteIndented=true,IncludeFields=true}));
foreach(string model in new[]{"o240001","o241013"}){var bytes=Read(native,"obj/"+model+".objbnd.dcx");var n=BND4.Read(bytes);var v=FLVER2.Read(n.Files.Single(f=>f.ID==200).Bytes);var a=BND4.Read(n.Files.Single(f=>f.ID==400).Bytes);var rig=NativeAnimation.Skeleton(a.Files.Single(f=>f.ID==1000000).Bytes.ToArray());var phys=n.Files.Single(f=>f.ID==300).Bytes.ToArray();int header=64+BitConverter.ToUInt16(phys,62)+128;int data=BitConverter.ToInt32(phys,header+20),size=BitConverter.ToInt32(phys,header+24);int end=BitConverter.ToInt32(phys,header+36);var strings=new List<string>();for(int at=0;at<size;at++)if(phys[data+at]>=32&&phys[data+at]<127&&(at==0||phys[data+at-1]==0)){int stop=at;while(stop<size&&phys[data+stop]>=32&&phys[data+stop]<127)stop++;if(stop-at>=4&&stop<size&&phys[data+stop]==0)strings.Add(at+":"+System.Text.Encoding.ASCII.GetString(phys,data+at,stop-at));}
var tae=TAE.Read(a.Files.Single(f=>TAE.Is(f.Bytes.ToArray())).Bytes);File.WriteAllText(Path.Combine(output,model+"-native.json"),JsonSerializer.Serialize(new{Hash=Convert.ToHexStringLower(SHA256.HashData(bytes)),Files=n.Files.Select(f=>new{f.ID,f.Name,Length=f.Bytes.Length}),Nodes=v.Nodes.Select((node,i)=>new{Index=i,node.Name,node.ParentIndex,node.Translation,node.Rotation,node.Scale}),Dummies=v.Dummies.Select(d=>new{d.ReferenceID,d.ParentBoneIndex,d.AttachBoneIndex,d.Position,d.Forward,d.Upward}),Rig=rig,Clips=a.Files.Where(f=>f.ID>=1000000000).Select(f=>{var k=new NativeAnimation.Pack(f.Bytes.ToArray());int ac=k.Object("hkaSplineCompressedAnimation");return new{f.ID,f.Name,Duration=k.Float(ac+16),Frames=k.Int(ac+56)};}),Tae=tae.Animations.Select(t=>new{t.ID,t.AnimFileName,Events=t.Events.Select(e=>new{e.Type,e.StartTime,e.EndTime,Hex=Convert.ToHexString(e.GetParameterBytes(false))})}),Physics=new{Hash=Convert.ToHexStringLower(SHA256.HashData(phys)),Data=data,Size=size,Strings=strings,Raw=Convert.ToHexString(phys.AsSpan(data,size))}},new JsonSerializerOptions{WriteIndented=true,IncludeFields=true}));}
foreach(var(path,h)in hashes)if(Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(path)))!=h)throw new Exception("Input mutated");File.WriteAllText(Path.Combine(output,"hashes.json"),JsonSerializer.Serialize(hashes,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("PASS Parish source asset audit "+hashes.Count+" unchanged files");}}
